import { describe, it, expect, afterEach } from 'vitest';
import { mount, mockApi, respond } from '@xoong/test';
// In a real app: import table from './.xoong/operations.json' (generated by `xoong sync`).
import table from '../../cli/test/fixture-table.json';

let screen;
afterEach(() => screen?.unmount());

const users = () => [{ id: 1, name: 'Ada' }, { id: 2, name: 'Bob' }];

describe('user list screen', () => {
  it('renders rows from the API', async () => {
    const api = mockApi(table, { listUsers: users });
    screen = await mount(`<xo-view get="/users"><li xo-each="."><b>{name}</b></li></xo-view>`, { api });
    expect(screen.texts('li b')).toEqual(['Ada', 'Bob']);
  });

  it('shows the error from a failing API', async () => {
    const api = mockApi(table, { listUsers: () => respond(500, { title: 'Boom', detail: 'db down' }) });
    screen = await mount(`<xo-view get="/users"><p xo-if="$error" class="err">{$error.detail}</p></xo-view>`, { api });
    expect(screen.text('.err')).toBe('db down');
  });

  it('click calls the operation with params from the row, then refreshes', async () => {
    let name = 'Ada';
    const api = mockApi(table, {
      listUsers: () => [{ id: 1, name }],
      disableUser: () => { name = 'Ada (off)'; return { id: 1, name }; },
    });
    screen = await mount(`<xo-view get="/users"><li xo-each="."><b>{name}</b><button xo-click="POST /users/{id}/disable">off</button></li></xo-view>`, { api });
    await screen.click('button');
    expect(api.callsOf('disableUser')).toEqual([{ operation: 'disableUser', params: { id: '1' }, query: {}, body: undefined }]);
    expect(screen.text('b')).toBe('Ada (off)');
    expect(api.unhandled).toEqual([]);
    expect(screen.errors).toEqual([]);
  });

  it('form submit sends the fields as the body', async () => {
    const api = mockApi(table, { listUsers: users, createUser: ({ body }) => ({ id: 9, ...body }) });
    screen = await mount(`<xo-view><form xo-submit="POST /users"><input name="name"><button>add</button></form></xo-view>`, { api });
    await screen.submit('form', { name: 'Cy' });
    expect(api.callsOf('createUser')[0].body).toEqual({ name: 'Cy' });
  });

  it('click waits for a slow mutation before returning', async () => {
    let done = false;
    const api = mockApi(table, {
      listUsers: users,
      disableUser: async () => { await new Promise((r) => setTimeout(r, 40)); done = true; return { id: 1, name: 'Ada' }; },
    });
    screen = await mount(`<xo-view get="/users"><li xo-each="."><button xo-click="POST /users/{id}/disable">x</button></li></xo-view>`, { api });
    await screen.click('button');
    expect(done).toBe(true);
  });

  it('a form posted to an operation without a body sends no body', async () => {
    const api = mockApi(table, { getUser: () => ({ id: 1, name: 'Ada' }), disableUser: () => ({ id: 1, name: 'Ada' }) });
    screen = await mount(`<xo-view get="/users/{id}" p-id="1"><form xo-submit="POST /users/{id}/disable"><input name="x" value="1"><button>go</button></form></xo-view>`, { api });
    await screen.submit('form');
    expect(api.callsOf('disableUser')).toHaveLength(1);
    expect(api.callsOf('disableUser')[0].body).toBeUndefined();
    expect(screen.errors).toEqual([]);
  });

  it('a successful submit resets the form; xo-keep keeps the values; a failed submit keeps them', async () => {
    const api = mockApi(table, { createUser: ({ body }) => (body.name === 'bad' ? respond(422, { error: { code: 'invalid', message: 'bad name' } }) : { id: 9, ...body }) });
    screen = await mount(`<xo-view><form id="a" xo-submit="POST /users"><input name="name"></form>
      <form id="b" xo-submit="POST /users" xo-keep><input name="name"></form></xo-view>`, { api });
    await screen.submit('#a', { name: 'Cy' });
    await screen.submit('#b', { name: 'Di' });
    expect([screen.$('#a input').value, screen.$('#b input').value]).toEqual(['', 'Di']);
    await screen.submit('#a', { name: 'bad' });
    expect(screen.$('#a input').value).toBe('bad'); // an error must not throw away what the person typed
    expect(screen.errors).toHaveLength(1);
  });

  it('live events update the screen with no extra requests', async () => {
    const api = mockApi(table, { listUsers: users });
    screen = await mount(`<xo-view live get="/users"><li xo-each="."><b>{name}</b></li></xo-view>`, { api });
    const before = api.calls.length;
    await screen.push({ type: 'patch', entity: 'User', id: 2, path: '/name', value: 'Bobby', version: 1 });
    expect(screen.texts('li b')).toEqual(['Ada', 'Bobby']);
    expect(api.calls.length).toBe(before);
  });
});

describe('streamed operations declared in HTML', () => {
  const chat = { version: 1, operations: {
    chat: { id: 'chat', method: 'POST', path: '/chat', body: true, stream: true, uuid: ['client_message_id'], response: null },
  } };
  const sse = (...events) => new Response(new ReadableStream({
    start(c) { for (const e of events) c.enqueue(new TextEncoder().encode(`event: ${e.event}\ndata: ${JSON.stringify(e.data)}\n\n`)); c.close(); },
  }), { status: 200, headers: { 'content-type': 'text/event-stream' } });

  it('a submit on a streaming operation fills $stream while it runs and sends the idempotency key', async () => {
    const api = mockApi(chat, { chat: () => sse({ event: 'token', data: { text: 'Hel' } }, { event: 'token', data: { text: 'lo' } }, { event: 'done', data: { id: 7 } }) });
    screen = await mount(`<xo-view><ul><li xo-each="$stream"><b>{event}</b> {text}</li></ul>
      <p xo-if="$streaming" class="busy">typing</p>
      <form xo-submit="POST /chat"><input name="text"><button>send</button></form></xo-view>`, { api });
    await screen.submit('form', { text: 'hi' });
    expect(screen.texts('li')).toEqual(['token Hel', 'token lo', 'done']);
    expect(screen.$('.busy')).toBeNull(); // finished
    const body = api.callsOf('chat')[0].body;
    expect(body.text).toBe('hi');
    expect(body.client_message_id).toMatch(/^[0-9a-f-]{36}$/);
    expect(screen.errors).toEqual([]);
  });

  it('a failing streamed call reports xo-error and keeps the form values', async () => {
    const api = mockApi(chat, { chat: () => respond(429, { error: { code: 'rate_limited', message: 'slow down', retry_after_s: 3 } }) });
    screen = await mount(`<xo-view><form xo-submit="POST /chat"><input name="text"><button>send</button></form></xo-view>`, { api });
    await screen.submit('form', { text: 'hi' });
    expect(screen.errors).toHaveLength(1);
    expect(screen.errors[0]).toMatchObject({ status: 429, code: 'rate_limited', retryAfterS: 3 });
    expect(screen.$('input').value).toBe('hi');
  });
});

describe('streams and multipart in screens', () => {
  it('removing the view cancels a running stream', async () => {
    let aborted = false;
    const chat = { version: 1, operations: { chat: { id: 'chat', method: 'POST', path: '/chat', body: true, stream: true, response: null } } };
    const api = mockApi(chat, { chat: () => new Response(new ReadableStream({ start() { /* never ends */ }, cancel() { aborted = true; } }), { status: 200, headers: { 'content-type': 'text/event-stream' } }) });
    screen = await mount(`<xo-view><form xo-submit="POST /chat"><input name="text"><button>go</button></form></xo-view>`, { api });
    const form = screen.$('form');
    form.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    screen.$('xo-view').remove(); // navigate away
    await new Promise((r) => setTimeout(r, 20));
    expect(aborted).toBe(true);
  });

  it('a multipart form drops file inputs where no file was chosen', async () => {
    const up = { version: 1, operations: { upload: { id: 'upload', method: 'POST', path: '/f', body: true, multipart: true, response: null } } };
    let seen;
    const api = mockApi(up, { upload: () => respond(204, null) });
    const original = api.fetch;
    api.fetch = async (url, init) => { seen = init.body; return original(url, init); };
    screen = await mount(`<xo-view><form xo-submit="POST /f"><input name="title"><input type="file" name="photo"><button>go</button></form></xo-view>`, { api });
    await screen.submit('form', { title: 'x' });
    expect(seen instanceof FormData).toBe(true);
    expect([...seen.keys()]).toEqual(['title']);
  });
});

describe('p-<name>="?query" reads the page URL', () => {
  it('uses the query string value, and leaves the param out when it is absent', async () => {
    const api = mockApi(table, { getUser: ({ params }) => ({ id: Number(params.id), name: `User ${params.id}` }) });
    history.replaceState(null, '', '/post.html?id=7');
    screen = await mount(`<xo-view get="/users/{id}" p-id="?id"><b>{name}</b></xo-view>`, { api });
    expect(screen.text('b')).toBe('User 7');
    expect(api.callsOf('getUser')[0].params).toEqual({ id: '7' });
    screen.unmount();
    history.replaceState(null, '', '/post.html');
    const errors = [];
    const original = console.error;
    console.error = (...a) => errors.push(a.join(' '));
    try { screen = await mount(`<xo-view get="/users/{id}" p-id="?id"><b>{name}</b></xo-view>`, { api: mockApi(table, { getUser: () => ({ id: 1, name: 'x' }) }) }); } finally { console.error = original; history.replaceState(null, '', '/'); }
    expect(screen.text('b')).toBe(''); // no id in the URL: the request cannot be built, and nothing is rendered
    expect(errors.join('\n')).toMatch(/id/);
  });
});

describe('xo-optimistic', () => {
  it('shows the new value before the server answers, and takes it back on failure', async () => {
    let release, fail = false;
    const gate = new Promise((r) => { release = r; });
    const api = mockApi(table, { listUsers: () => [{ id: 1, name: 'Ada' }], disableUser: async () => { await gate; return fail ? respond(500, { title: 'Boom' }) : { id: 1, name: 'Ada', status: 'disabled' }; } });
    screen = await mount(`<xo-view get="/users"><li xo-each="."><b>{name}</b> <i>{status}</i><button xo-click="POST /users/{id}/disable" xo-optimistic="status=disabled">off</button></li></xo-view>`, { api });
    screen.$('button').click();
    await new Promise((r) => setTimeout(r, 10));
    expect(screen.text('i')).toBe('disabled'); // optimistic, the request is still pending
    fail = true;
    release();
    await screen.settle();
    expect(screen.text('i')).toBe(''); // the failure took it back
    expect(screen.errors).toHaveLength(1);
  });

  it('reports a button that is not on a stored item', async () => {
    const seen = [];
    const original = console.error;
    console.error = (...a) => seen.push(a.join(' '));
    try {
      screen = await mount(`<xo-view p-id="1"><button xo-click="POST /users/{id}/disable" xo-optimistic="status=x">go</button></xo-view>`, { api: mockApi(table, { disableUser: () => ({ id: 1, name: 'A' }) }) });
      await screen.click('button');
    } finally { console.error = original; }
    expect(seen.join('\n')).toMatch(/xo-optimistic needs a stored entity/);
  });
});
